const FILES = {
 '/': ['',''],
 '/admin.html': ['text/html; charset=utf-8',''],
 '/icon-512.png': ['image/png',''],
 '/ativar.html': ['text/html; charset=utf-8',''],
 '/sw.js': ['application/javascript; charset=utf-8',''],
 '/logo-app.png': ['image/png',''],
 '/icon-192.png': ['image/png',''],
 '/index.html': ['text/html; charset=utf-8',''],
 '/admin.webmanifest': ['application/manifest+json',''],
};

export default {
  async fetch(req) {
    const u = new URL(req.url);
    let p = u.pathname;
    if (p === '/' || p === '') p = '/index.html';
    const f = FILES[p];
    if (!f) return new Response('NÃ£o encontrado', { status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
    const bytes = Uint8Array.from(atob(f[1]), c => c.charCodeAt(0));
    return new Response(bytes, { headers: { 'Content-Type': f[0], 'Cache-Control': 'no-cache', 'Service-Worker-Allowed': '/' } });
  }
};